import * as AiAssistance from './ai_assistance.js';

describe('AiHistoryStorage', () => {
  const agent1: AiAssistance.AiHistoryStorage.SerializedConversation = {
    id: 'id1',
    type: AiAssistance.AiHistoryStorage.ConversationType.STYLING,
    history: [],
  };
  const agent2: AiAssistance.AiHistoryStorage.SerializedConversation = {
    id: 'id2',
    type: AiAssistance.AiHistoryStorage.ConversationType.FILE,
    history: [],
  };
  const agent3: AiAssistance.AiHistoryStorage.SerializedConversation = {
    id: 'id3',
    type: AiAssistance.AiHistoryStorage.ConversationType.NETWORK,
    history: [],
  };
  const agent4: AiAssistance.AiHistoryStorage.SerializedConversation = {
    id: 'id4',
    type: AiAssistance.AiHistoryStorage.ConversationType.STYLING,
    history: [
      {
        type: AiAssistance.AiAgent.ResponseType.USER_QUERY,
        query: 'text',
        imageId: 'image-id1',
        imageInput: undefined,
      },
      {
        type: AiAssistance.AiAgent.ResponseType.ANSWER,
        text: 'answer',
        complete: true,
      },
      {
        type: AiAssistance.AiAgent.ResponseType.USER_QUERY,
        query: 'text',
        imageId: 'image-id2',
        imageInput: undefined,
      },
    ],
  };
  const serializedImage1: AiAssistance.AiHistoryStorage.SerializedImage = {
    id: 'image-id1',
    data: 'imageInput',
    mimeType: 'image/jpeg',
  };
  const serializedImage2: AiAssistance.AiHistoryStorage.SerializedImage = {
    id: 'image-id2',
    data: 'imageInput',
    mimeType: 'image/jpeg',
  };

  beforeEach(() => {
    let data: Record<string, string> = {};
    const dummyStorage = new Common.Settings.SettingsStorage({}, {
      get(setting) {
        return Promise.resolve(data[setting]);
      },
      set(setting, value) {
        data[setting] = value;
      },
      clear() {
        data = {};
      },
      remove(setting) {
        delete data[setting];
      },
      register(_setting) {},
    });
    // eslint-disable-next-line @devtools/no-instance-of-migrated-singletons
    Common.Settings.Settings.instance({
      forceNew: true,
      syncedStorage: dummyStorage,
      globalStorage: dummyStorage,
      localStorage: dummyStorage,
      settingRegistrations: Common.SettingRegistration.getRegisteredSettings(),
      console: new Common.Console.Console(),
    });
  });

  function getStorage(maxStorageSize?: number) {
    return AiAssistance.AiHistoryStorage.AiHistoryStorage.instance({forceNew: true, maxStorageSize});
  }

  it('should create and retrieve history entry', async () => {
    const storage = getStorage();
    await storage.upsertHistoryEntry(agent1);
    assert.deepEqual(
        storage.getHistory(),
        [{
          id: 'id1',
          type: 'freestyler' as AiAssistance.AiHistoryStorage.ConversationType,
          history: [],
        }],
    );
    await storage.upsertHistoryEntry(agent2);
    assert.deepEqual(
        storage.getHistory(),
        [
          {
            id: 'id1',
            type: 'freestyler' as AiAssistance.AiHistoryStorage.ConversationType,
            history: [],
          },
          {
            id: 'id2',
            type: 'drjones-file' as AiAssistance.AiHistoryStorage.ConversationType,
            history: [],
          },
        ],
    );
  });

  it('should cap history entries to MAX_CONVERSATIONS_COUNT and evict oldest and clean up their images', async () => {
    const storage = getStorage();

    await storage.upsertImage(serializedImage1);
    const oldestConv: AiAssistance.AiHistoryStorage.SerializedConversation = {
      id: 'oldest-id',
      type: AiAssistance.AiHistoryStorage.ConversationType.STYLING,
      history: [
        {
          type: AiAssistance.AiAgent.ResponseType.USER_QUERY,
          query: 'oldest text',
          imageId: 'image-id1',
          imageInput: undefined,
        },
      ],
    };
    await storage.upsertHistoryEntry(oldestConv);

    await storage.upsertImage(serializedImage2);
    const newerConvWithImage: AiAssistance.AiHistoryStorage.SerializedConversation = {
      id: 'newer-id-with-image',
      type: AiAssistance.AiHistoryStorage.ConversationType.STYLING,
      history: [
        {
          type: AiAssistance.AiAgent.ResponseType.USER_QUERY,
          query: 'newer text',
          imageId: 'image-id2',
          imageInput: undefined,
        },
      ],
    };
    await storage.upsertHistoryEntry(newerConvWithImage);

    assert.deepEqual(
        storage.getImageHistory(),
        [serializedImage1, serializedImage2],
    );

    // Insert dummy entries to trigger eviction
    for (let i = 0; i < AiAssistance.AiHistoryStorage.MAX_CONVERSATIONS_COUNT - 1; i++) {
      await storage.upsertHistoryEntry({
        id: `dummy-id-${i}`,
        type: AiAssistance.AiHistoryStorage.ConversationType.STYLING,
        history: [],
      });
    }

    const history = storage.getHistory();
    assert.lengthOf(history, 50);

    assert.isUndefined(history.find(c => c.id === 'oldest-id'));
    assert.isDefined(history.find(c => c.id === 'newer-id-with-image'));

    assert.deepEqual(
        storage.getImageHistory(),
        [serializedImage2],
    );
  });

  it('should update history entries correctly', async () => {
    const storage = getStorage();
    await storage.upsertHistoryEntry(agent1);
    await storage.upsertHistoryEntry(agent2);
    await storage.upsertHistoryEntry({
      ...agent1,
      history: [
        {
          type: AiAssistance.AiAgent.ResponseType.USER_QUERY,
          query: 'text',
        },
      ],
    });
    assert.deepEqual(
        storage.getHistory(),
        [
          {
            id: 'id1',
            type: 'freestyler' as AiAssistance.AiHistoryStorage.ConversationType,
            history: [
              {
                type: AiAssistance.AiAgent.ResponseType.USER_QUERY,
                query: 'text',
              },
            ],
          },
          {
            id: 'id2',
            type: 'drjones-file' as AiAssistance.AiHistoryStorage.ConversationType,
            history: [],
          },
        ],
    );

    await storage.upsertHistoryEntry(agent3);
    assert.deepEqual(
        storage.getHistory(),
        [
          {
            id: 'id1',
            type: 'freestyler' as AiAssistance.AiHistoryStorage.ConversationType,
            history: [
              {
                type: AiAssistance.AiAgent.ResponseType.USER_QUERY,
                query: 'text',
              },
            ],
          },
          {
            id: 'id2',
            type: 'drjones-file' as AiAssistance.AiHistoryStorage.ConversationType,
            history: [],
          },
          {
            id: 'id3',
            type: 'drjones-network-request' as AiAssistance.AiHistoryStorage.ConversationType,
            history: [],
          },
        ],
    );
    assert.deepEqual(
        storage.getImageHistory(),
        [],
    );

    await storage.upsertImage(serializedImage1);
    await storage.upsertImage(serializedImage2);
    await storage.upsertHistoryEntry(agent4);
    assert.deepEqual(
        storage.getHistory(),
        [
          {
            id: 'id1',
            type: 'freestyler' as AiAssistance.AiHistoryStorage.ConversationType,
            history: [
              {
                type: AiAssistance.AiAgent.ResponseType.USER_QUERY,
                query: 'text',
              },
            ],
          },
          {
            id: 'id2',
            type: 'drjones-file' as AiAssistance.AiHistoryStorage.ConversationType,
            history: [],
          },
          {
            id: 'id3',
            type: 'drjones-network-request' as AiAssistance.AiHistoryStorage.ConversationType,
            history: [],
          },
          {
            id: 'id4',
            type: 'freestyler' as AiAssistance.AiHistoryStorage.ConversationType,
            history: [
              {
                type: AiAssistance.AiAgent.ResponseType.USER_QUERY,
                query: 'text',
                imageId: 'image-id1',
                imageInput: undefined,
              },
              {
                type: AiAssistance.AiAgent.ResponseType.ANSWER,
                text: 'answer',
                complete: true,
              },
              {
                type: AiAssistance.AiAgent.ResponseType.USER_QUERY,
                query: 'text',
                imageId: 'image-id2',
                imageInput: undefined,
              },
            ],
          },
        ],
    );
    assert.deepEqual(
        storage.getImageHistory(),
        [
          {
            id: 'image-id1',
            data: 'imageInput',
            mimeType: 'image/jpeg',
          },
          {
            id: 'image-id2',
            data: 'imageInput',
            mimeType: 'image/jpeg',
          },
        ],
    );
  });

  it('should delete a single entry', async () => {
    const storage = getStorage();
    await storage.upsertHistoryEntry(agent1);
    await storage.upsertHistoryEntry(agent2);
    await storage.upsertHistoryEntry(agent3);
    await storage.deleteHistoryEntry('id2');
    assert.deepEqual(
        storage.getHistory(),
        [
          {
            id: 'id1',
            type: 'freestyler' as AiAssistance.AiHistoryStorage.ConversationType,
            history: [],
          },
          {
            id: 'id3',
            type: 'drjones-network-request' as AiAssistance.AiHistoryStorage.ConversationType,
            history: [],
          },
        ],
    );
  });

  it('should delete image history entry', async () => {
    const storage = getStorage();
    await storage.upsertHistoryEntry(agent1);
    await storage.upsertHistoryEntry(agent2);
    await storage.upsertHistoryEntry(agent3);
    await storage.upsertImage(serializedImage1);
    await storage.upsertImage(serializedImage2);
    await storage.upsertHistoryEntry(agent4);
    await storage.deleteHistoryEntry('id4');
    assert.deepEqual(
        storage.getHistory(),
        [
          {
            id: 'id1',
            type: 'freestyler' as AiAssistance.AiHistoryStorage.ConversationType,
            history: [],
          },
          {
            id: 'id2',
            type: 'drjones-file' as AiAssistance.AiHistoryStorage.ConversationType,
            history: [],
          },
          {
            id: 'id3',
            type: 'drjones-network-request' as AiAssistance.AiHistoryStorage.ConversationType,
            history: [],
          },
        ],
    );
    assert.deepEqual(
        storage.getImageHistory(),
        [],
    );
  });

  it('should delete all entries', async () => {
    const storage = getStorage();
    await storage.upsertHistoryEntry(agent1);
    await storage.upsertHistoryEntry(agent2);
    await storage.upsertHistoryEntry(agent3);
    await storage.upsertImage(serializedImage1);
    await storage.upsertImage(serializedImage2);
    await storage.upsertHistoryEntry(agent4);
    await storage.addRecentPrompt('prompt');
    const historyDeletedPromise =
        storage.once('AiHistoryDeleted' as AiAssistance.AiHistoryStorage.Events.HISTORY_DELETED);
    await storage.deleteAll();
    assert.deepEqual(
        storage.getHistory(),
        [],
    );
    assert.deepEqual(
        storage.getImageHistory(),
        [],
    );
    assert.deepEqual(
        storage.getRecentPrompts(),
        [],
    );
    await historyDeletedPromise;
  });

  it('should store and retrieve recent prompts', async () => {
    const storage = getStorage();
    await storage.addRecentPrompt('prompt 1');
    await storage.addRecentPrompt('prompt 2');
    assert.deepEqual(storage.getRecentPrompts(), ['prompt 2', 'prompt 1']);
  });

  it('should move existing prompts to the top and deduplicate', async () => {
    const storage = getStorage();
    await storage.addRecentPrompt('prompt 1');
    await storage.addRecentPrompt('prompt 2');
    await storage.addRecentPrompt('prompt 1');
    assert.deepEqual(storage.getRecentPrompts(), ['prompt 1', 'prompt 2']);
  });

  it('should prune recent prompts by count', async () => {
    const storage = getStorage();
    for (let i = 0; i < AiAssistance.AiHistoryStorage.MAX_RECENT_PROMPTS_COUNT + 5; i++) {
      await storage.addRecentPrompt(`prompt ${i}`);
    }
    const recentPrompts = storage.getRecentPrompts();
    assert.lengthOf(recentPrompts, AiAssistance.AiHistoryStorage.MAX_RECENT_PROMPTS_COUNT);
    assert.strictEqual(recentPrompts[0], `prompt ${AiAssistance.AiHistoryStorage.MAX_RECENT_PROMPTS_COUNT + 4}`);
  });

  it('should prune recent prompts by total character length', async () => {
    const storage = getStorage();
    const largePrompt = 'a'.repeat(AiAssistance.AiHistoryStorage.RECENT_PROMPTS_SIZE_LIMIT);
    await storage.addRecentPrompt('small prompt');
    await storage.addRecentPrompt(largePrompt);

    const recentPrompts = storage.getRecentPrompts();
    assert.lengthOf(recentPrompts, 1);
    assert.strictEqual(recentPrompts[0], largePrompt);

    await storage.addRecentPrompt('another small');
    const recentPrompts2 = storage.getRecentPrompts();
    assert.lengthOf(recentPrompts2, 1);
    assert.strictEqual(recentPrompts2[0], 'another small');
  });

  it('should not store empty or whitespace-only prompts', async () => {
    const storage = getStorage();
    await storage.addRecentPrompt('');
    await storage.addRecentPrompt('   ');
    assert.lengthOf(storage.getRecentPrompts(), 0);
  });

  it('should limit the amount of stored images', async () => {
    const MAX_STORAGE_SIZE = 2;
    const storage = getStorage(MAX_STORAGE_SIZE);

    await storage.upsertImage({
      id: 'image-id1',
      data: '1',
      mimeType: 'image/jpeg',
    });
    await storage.upsertHistoryEntry(agent1);
    await storage.upsertImage({
      id: 'image-id2',
      data: '2',
      mimeType: 'image/jpeg',
    });
    await storage.upsertImage({
      id: 'image-id3',
      data: '3',
      mimeType: 'image/jpeg',
    });
    await storage.upsertHistoryEntry(agent2);
    await storage.upsertImage({
      id: 'image-id4',
      data: '4',
      mimeType: 'image/jpeg',
    });
    await storage.upsertHistoryEntry(agent3);
    const imageHistory = storage.getImageHistory();
    const imageData1 = imageHistory.find(item => item.id === 'image-id1');
    const imageData2 = imageHistory.find(item => item.id === 'image-id2');
    const imageData3 = imageHistory.find(item => item.id === 'image-id3');
    const imageData4 = imageHistory.find(item => item.id === 'image-id4');

    assert.notExists(imageData1);
    assert.notExists(imageData2);
    assert.deepEqual(imageData3, {
      id: 'image-id3',
      data: '3',
      mimeType: 'image/jpeg',
    });
    assert.deepEqual(imageData4, {
      id: 'image-id4',
      data: '4',
      mimeType: 'image/jpeg',
    });
  });

  describe('Conversation', () => {
    describe('title', () => {
      it('should return undefined if there is not USER_QUERY entry in history', () => {
        const conversation = new AiAssistance.AiConversation.AiConversation(
            {type: AiAssistance.AiHistoryStorage.ConversationType.STYLING, data: []});

        assert.isUndefined(conversation.title);
      });

      it('should return full title if the first USER_QUERY is less than 80 characters', () => {
        const conversation = new AiAssistance.AiConversation.AiConversation({
          type: AiAssistance.AiHistoryStorage.ConversationType.STYLING,
          data: [{
            type: AiAssistance.AiAgent.ResponseType.USER_QUERY,
            query: 'this is less than 80',
          }],
        });
        assert.strictEqual(conversation.title, 'this is less than 80');
      });

      it('should return first 80 characters of the title with ellipis if the first USER_QUERY is more than 80 characters',
         () => {
           const conversation = new AiAssistance.AiConversation.AiConversation({
             type: AiAssistance.AiHistoryStorage.ConversationType.STYLING,
             data: [{
               type: AiAssistance.AiAgent.ResponseType.USER_QUERY,
               query:
                   'this is more than 80 characters because I\'m just going to keep typing words and words and words until it\'s really, really long, see?',
             }],
           });

           assert.strictEqual(
               conversation.title,
               'this is more than 80 characters because I\'m just going to keep typing words and …');
         });
    });

    describe('addHistoryItem', () => {
      const historyItem1: AiAssistance.AiAgent.ResponseData = {
        type: AiAssistance.AiAgent.ResponseType.USER_QUERY,
        query: 'text',
        imageInput: {
          inlineData: {
            data: '1',
            mimeType: 'image/jpeg',
          },
        },
        imageId: 'image-id1',
      };
      const historyItem2: AiAssistance.AiAgent.ResponseData = {
        type: AiAssistance.AiAgent.ResponseType.USER_QUERY,
        query: 'text',
        imageInput: {
          inlineData: {
            data: '2',
            mimeType: 'image/jpeg',
          },
        },
        imageId: 'image-id2',
      };

      it('should store images and text conversation separately', async () => {
        const storage = getStorage();
        sinon.stub(AiAssistance.AiHistoryStorage.AiHistoryStorage, 'instance').returns(storage);
        const conversation1 = new AiAssistance.AiConversation.AiConversation({
          type: AiAssistance.AiHistoryStorage.ConversationType.STYLING,
          data: [],
          id: 'id1',
          isReadOnly: false,
        });
        await conversation1.addHistoryItem(historyItem1);
        const conversation2 = new AiAssistance.AiConversation.AiConversation({
          type: AiAssistance.AiHistoryStorage.ConversationType.STYLING,
          data: [],
          id: 'id2',
          isReadOnly: false,
        });
        await conversation2.addHistoryItem(historyItem2);

        const imageHistory = storage.getImageHistory();
        assert.lengthOf(imageHistory, 2);
        assert.deepEqual(imageHistory[0], {
          id: 'image-id1',
          data: '1',
          mimeType: 'image/jpeg',
        });
        assert.deepEqual(imageHistory[1], {
          id: 'image-id2',
          data: '2',
          mimeType: 'image/jpeg',
        });

        const historyWithoutImages = storage.getHistory();
        assert.lengthOf(historyWithoutImages, 2);
        assert.deepEqual(historyWithoutImages[0], {
          id: 'id1',
          type: AiAssistance.AiHistoryStorage.ConversationType.STYLING,
          history: [{
            type: AiAssistance.AiAgent.ResponseType.USER_QUERY,
            query: 'text',
            imageId: 'image-id1',
          }],
        });
        assert.deepEqual(historyWithoutImages[1], {
          id: 'id2',
          type: AiAssistance.AiHistoryStorage.ConversationType.STYLING,
          history: [{
            type: AiAssistance.AiAgent.ResponseType.USER_QUERY,
            query: 'text',
            imageInput: undefined,
            imageId: 'image-id2',
          }],
        });
      });

      it('should have empty image data for image not present in history', async () => {
        const MAX_STORAGE_SIZE = 1;
        const storage = getStorage(MAX_STORAGE_SIZE);
        sinon.stub(AiAssistance.AiHistoryStorage.AiHistoryStorage, 'instance').returns(storage);
        const conversation1 = new AiAssistance.AiConversation.AiConversation({
          type: AiAssistance.AiHistoryStorage.ConversationType.STYLING,
          data: [],
          id: 'id1',
          isReadOnly: false,
        });
        await conversation1.addHistoryItem(historyItem1);
        const conversation2 = new AiAssistance.AiConversation.AiConversation({
          type: AiAssistance.AiHistoryStorage.ConversationType.STYLING,
          data: [],
          id: 'id2',
          isReadOnly: false,
        });
        await conversation2.addHistoryItem(historyItem2);

        const imageHistory = storage.getImageHistory();
        assert.lengthOf(imageHistory, 1);
        const historyWithoutImages = storage.getHistory();
        assert.lengthOf(historyWithoutImages, 2);
        const conversationFromHistory = historyWithoutImages.map(
            item => AiAssistance.AiConversation.AiConversation.fromSerializedConversation(item));
        assert.lengthOf(conversationFromHistory, 2);
        assert.deepEqual(conversationFromHistory[0].history, [{
                           type: AiAssistance.AiAgent.ResponseType.USER_QUERY,
                           query: 'text',
                           imageInput: {
                             inlineData: {
                               data: AiAssistance.AiConversation.NOT_FOUND_IMAGE_DATA,
                               mimeType: 'image/jpeg',
                             },
                           },
                           imageId: 'image-id1',
                         }]);
        assert.deepEqual(conversationFromHistory[1].history, [{
                           type: AiAssistance.AiAgent.ResponseType.USER_QUERY,
                           query: 'text',
                           imageInput: {
                             inlineData: {
                               data: '2',
                               mimeType: 'image/jpeg',
                             },
                           },
                           imageId: 'image-id2',
                         }]);
      });
    });
  });

  describe('getConversationMarkdown', function() {
    const snapshotTester = new SnapshotTester(this, import.meta);

    it('should generate markdown from a conversation', function() {
      const fakeTime = new Date('2024-01-01T00:00:00.000Z');
      sinon.useFakeTimers(fakeTime);

      const history: AiAssistance.AiAgent.ResponseData[] = [
        {
          type: AiAssistance.AiAgent.ResponseType.USER_QUERY,
          query: 'What is the color of the sky?',
        },
        {
          type: AiAssistance.AiAgent.ResponseType.CONTEXT,
          details: [
            {title: 'Detail 1', text: 'Some detail'},
            {title: 'Detail 2', text: 'const a = 1;', codeLang: 'js'},
          ],
        },
        {
          type: AiAssistance.AiAgent.ResponseType.TITLE,
          title: 'Thinking about it',
        },
        {
          type: AiAssistance.AiAgent.ResponseType.THOUGHT,
          thought: 'The user is asking about colors.',
        },
        {
